    isClosed: () => closed, url: () => 'about:blank',
    locator: () => ({ first: () => ({}) }),
    addLocatorHandler: async () => { closed = true; throw new Error('Target page, context or browser has been closed'); }
  });
  const context = Object.assign(new EventEmitter(), { pages: () => [page] });
